import { Cart, CartItem, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Add a new line item to the wish list.
*/
export type AddToWishList = {
    events: Array<Cart | CartItem | Identity | PartyIdentification | ErrorEvent>;
}

export class AddToWishListBuilder {

    private addToWishList: AddToWishList = {
        events: []
    }

    private cart!: Cart;
    private cartItem!: CartItem;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : AddToWishListBuilder {
        this.cart = cart;
        return this;
    }
    public withCartItem(cartItem: CartItem) : AddToWishListBuilder {
        this.cartItem = cartItem;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : AddToWishListBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : AddToWishListBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : AddToWishListBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : AddToWishList {
        if(this.cart) {
            this.addToWishList.events.push(this.cart);
        }
        if(this.cartItem) {
            this.addToWishList.events.push(this.cartItem);
        }
        if(this.errorEvent) {
            this.addToWishList.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.addToWishList.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.addToWishList.events.push(this.partyIdentification);
        }

        return this.addToWishList;
    }
}
